mapper.select:
SELECT id, user_id AS userId, target_type AS targetType, target_id AS targetId,
       route_mode AS routeMode, selected_variant AS selectedVariant, selected_recipe_key AS selectedRecipeKey,
       max_depth AS maxDepth, title, note, url, snapshot_json AS snapshotJson,
       deleted, created_at AS createdAt, updated_at AS updatedAt
FROM user_saved_routes
WHERE user_id = #{userId}
  AND target_type = #{targetType}
  AND target_id = #{targetId}
  AND route_mode = #{routeMode}
LIMIT 1

mapper.update:
UPDATE user_saved_routes
SET deleted = 1,
    updated_at = NOW()
WHERE user_id = #{userId}
  AND id = #{id}
  AND deleted = 0
